import os
import re


def to_roman(n):
    vals = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
            (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
            (5, "V"), (4, "IV"), (1, "I")]
    out = []
    for v, s in vals:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)


def from_roman(s):
    m = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(s):
        v = m[ch]
        if i + 1 < len(s) and m[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(s):
    if re.fullmatch(r"[0-9]+", s):
        n = int(s)
        if 1 <= n <= 3999:
            return to_roman(n)
        return "invalid"
    if re.fullmatch(r"[IVXLCDM]+", s):
        n = from_roman(s)
        if 1 <= n <= 3999 and to_roman(n) == s:
            return str(n)
    return "invalid"


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "numbers.txt"), encoding="utf-8", errors="replace") as f:
        text = f.read()
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        print(f"{s} = {convert(s)}")


