import os


def check(line):
    pairs = {')': '(', ']': '[', '}': '{'}
    closer = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i, ch in enumerate(line):
        if ch in closer:
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return "col %d: unexpected %s" % (i + 1, ch)
            exp = closer[stack[-1]]
            if exp != ch:
                return "col %d: expected %s, found %s" % (i + 1, exp, ch)
            stack.pop()
    if stack:
        return "unclosed " + closer[stack[-1]]
    return "ok"


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "snippets.txt"), "r", encoding="utf-8", newline="") as f:
        data = f.read()
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        out.append(check(line))
    if out:
        print("\n".join(out))


