import os
import sys
import heapq


def main():
    d = os.environ.get("INPUT", "input")
    path = os.path.join(d, "routes.txt")
    with open(path, encoding="utf-8", errors="surrogateescape") as f:
        lines = f.read().splitlines()

    adj = {}
    trips = []
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        p = s.split()
        if p[0] == "road" and len(p) >= 4:
            x, y, c = p[1], p[2], int(p[3])
            adj.setdefault(x, {})
            adj.setdefault(y, {})
            if y not in adj[x] or adj[x][y] > c:
                adj[x][y] = c
                adj[y][x] = c
        elif p[0] == "trip" and len(p) >= 3:
            trips.append((p[1], p[2]))

    cache = {}

    def dists(t):
        if t in cache:
            return cache[t]
        dist = {t: 0}
        pq = [(0, t)]
        while pq:
            dd, u = heapq.heappop(pq)
            if dd > dist.get(u, float("inf")):
                continue
            for v, w in adj.get(u, {}).items():
                nd = dd + w
                if nd < dist.get(v, float("inf")):
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[t] = dist
        return dist

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        dist = dists(y)
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        path_nodes = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj[u].items():
                if v in dist and w + dist[v] == dist[u]:
                    if best is None or v.encode("utf-8", "surrogateescape") < best.encode("utf-8", "surrogateescape"):
                        best = v
            u = best
            path_nodes.append(u)
        out.append(" -> ".join(path_nodes) + f" {dist[x]}")

    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()

import json
import os
import sys


def merge(base, override):
    result = dict(base)
    for key, val in override.items():
        if val is None:
            result.pop(key, None)
        elif isinstance(val, dict):
            b = result.get(key)
            result[key] = merge(b if isinstance(b, dict) else {}, val)
        else:
            result[key] = val
    return result


def flatten(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
        else:
            for k, v in value.items():
                flatten(v, path + "." + k if path != "" else k, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
        else:
            for i, v in enumerate(value):
                flatten(v, path + "." + str(i) if path != "" else str(i), out)
    else:
        out.append((path, json.dumps(value, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), encoding="utf-8") as f:
        override = json.load(f)
    merged = merge(base, override)
    out = []
    flatten(merged, "", out)
    out.sort(key=lambda p: p[0].encode("utf-8"))
    data = "".join("%s=%s\n" % (p, v) for p, v in out)
    sys.stdout.buffer.write(data.encode("utf-8"))
    sys.stdout.buffer.flush()


