import os


def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]

    with open(os.path.join(inp, "app.log"), "rb") as f:
        text = f.read().decode("utf-8", errors="surrogateescape")

    buckets = {"error": [], "warn": [], "info": []}
    other = 0

    for line in text.split("\n"):
        if line.strip() == "":
            continue
        fields = line.split(" ")
        level = fields[1].upper() if len(fields) >= 3 else None
        if level == "ERROR":
            buckets["error"].append(line)
        elif level in ("WARN", "WARNING"):
            buckets["warn"].append(line)
        elif level == "INFO":
            buckets["info"].append(line)
        else:
            other += 1

    for name, lines in buckets.items():
        with open(os.path.join(out, name + ".log"), "wb") as f:
            data = "".join(l + "\n" for l in lines)
            f.write(data.encode("utf-8", errors="surrogateescape"))

    print("error %d" % len(buckets["error"]))
    print("warn %d" % len(buckets["warn"]))
    print("info %d" % len(buckets["info"]))
    print("other %d" % other)


if __name__ == "__main__":
    main()

import os
import sys
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                counts = {str(k): int(v) for k, v in data.items()}
        except (ValueError, OSError):
            counts = {}

    with open(os.path.join(input_dir, "visits.txt"), "rb") as f:
        raw = f.read()

    text = raw.decode("utf-8", errors="surrogateescape")
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line:
            continue
        counts[line] = counts.get(line, 0) + 1

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(counts, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, kv_path)

    items = sorted(
        counts.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8", "surrogateescape")),
    )
    out = sys.stdout.buffer
    for page, total in items:
        out.write(page.encode("utf-8", "surrogateescape") + b" " + str(total).encode() + b"\n")
    out.flush()


