import os
import sys
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]

    users = {}
    try:
        with open(kv_path, "r", encoding="utf-8") as f:
            data = f.read()
        if data.strip():
            users = json.loads(data)
    except FileNotFoundError:
        pass

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8") as f:
        content = f.read()

    out = []
    for raw in content.split("\n"):
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        n = len(parts)
        if cmd == "put" and n == 4:
            users[parts[1]] = {"id": parts[1], "name": parts[2], "email": parts[3]}
            out.append("ok " + parts[1])
        elif cmd == "rename" and n == 3:
            if parts[1] in users:
                users[parts[1]]["name"] = parts[2]
                out.append("ok " + parts[1])
            else:
                out.append("missing " + parts[1])
        elif cmd == "get" and n == 2:
            u = users.get(parts[1])
            if u is None:
                out.append("missing " + parts[1])
            else:
                out.append(json.dumps(
                    {"id": u["id"], "name": u["name"], "email": u["email"]},
                    separators=(",", ":"), ensure_ascii=False))
        elif cmd == "del" and n == 2:
            if parts[1] in users:
                del users[parts[1]]
                out.append("ok " + parts[1])
            else:
                out.append("missing " + parts[1])
        elif cmd == "count" and n == 1:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(users, f, ensure_ascii=False)
    os.replace(tmp, kv_path)

    if out:
        sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8"))
        sys.stdout.buffer.flush()


main()

import os
import re
import json


def main():
    input_dir = os.environ.get("INPUT", "input")
    kv_path = os.environ.get("LIMITS", "limits.json")

    state = {}
    try:
        with open(kv_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            state = {k: v for k, v in data.items() if isinstance(v, int)}
    except (OSError, ValueError):
        state = {}

    int_re = re.compile(r"[+-]?[0-9]+")
    out = []
    max_win = None

    path = os.path.join(input_dir, "requests.txt")
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        lines = []

    for line in lines:
        parts = line.split()
        if len(parts) != 2 or not int_re.fullmatch(parts[0]):
            continue
        ts = int(parts[0])
        client = parts[1]
        win = ts // 60
        if max_win is None or win > max_win:
            max_win = win
        key = json.dumps([win, client])
        cnt = state.get(key, 0)
        if cnt < 3:
            state[key] = cnt + 1
            out.append(f"{ts} {client} allow")
        else:
            out.append(f"{ts} {client} deny")

    if max_win is not None:
        pruned = {}
        for k, v in state.items():
            try:
                w = json.loads(k)[0]
            except (ValueError, IndexError, TypeError):
                continue
            if w >= max_win - 1:
                pruned[k] = v
        state = pruned

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
    os.replace(tmp, kv_path)

    if out:
        print("\n".join(out))


main()

import os
import json


def main():
    input_dir = os.environ["INPUT"]
    board_path = os.environ["BOARD"]

    board = {}
    if os.path.exists(board_path):
        try:
            with open(board_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                for k, v in data.items():
                    board[k] = [int(v[0]), int(v[1])]
        except Exception:
            board = {}

    def add(name, pts):
        e = board.setdefault(name, [0, 0])
        e[0] += pts
        e[1] += 1

    games = os.path.join(input_dir, "games.txt")
    if os.path.isfile(games):
        with open(games, "rb") as f:
            text = f.read().decode("utf-8", errors="surrogateescape")
        for line in text.split("\n"):
            parts = line.strip().split()
            if len(parts) == 2:
                w, l = parts
                if w == l:
                    continue
                add(w, 3)
                add(l, 0)
            elif len(parts) == 3 and parts[2] == "draw":
                a, b = parts[0], parts[1]
                if a == b:
                    continue
                add(a, 1)
                add(b, 1)

    tmp = board_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(board, f)
    os.replace(tmp, board_path)

    def key(item):
        name, (pts, played) = item
        return (-pts, played, name.encode("utf-8", errors="surrogateescape"))

    ranked = sorted(board.items(), key=key)[:3]
    out = []
    for i, (name, (pts, played)) in enumerate(ranked, 1):
        out.append("%d. %s %d %d\n" % (i, name, pts, played))
    os.write(1, "".join(out).encode("utf-8", errors="surrogateescape"))


main()

import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV_PATH = os.environ.get("COUNTS", "counts.json")
LOCK = threading.Lock()
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")


def load():
    try:
        with open(KV_PATH, "r") as f:
            d = json.load(f)
        if isinstance(d, dict):
            return {str(k): int(v) for k, v in d.items()}
    except (OSError, ValueError):
        pass
    return {}


def save(d):
    tmp = KV_PATH + ".tmp"
    with open(tmp, "w") as f:
        json.dump(d, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV_PATH)


DATA = load()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        if n > 0:
            self.rfile.read(n)
        method = self.command
        path = self.path
        if method == "POST" and path.startswith("/hit/"):
            name = path[5:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                DATA[name] = DATA.get(name, 0) + 1
                c = DATA[name]
                save(DATA)
            return self.send_json(200, {"name": name, "count": c})
        if method == "GET" and path.startswith("/count/"):
            name = path[7:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                c = DATA.get(name, 0)
            return self.send_json(200, {"name": name, "count": c})
        if method == "GET" and path == "/top":
            with LOCK:
                items = sorted(DATA.items(), key=lambda kv: (-kv[1], kv[0].encode()))[:3]
            return self.send_json(200, [{"name": k, "count": v} for k, v in items])
        return self.send_json(404, {"error": "not found"})

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


def main():
    port = int(os.environ.get("PORT", "8000"))
    srv = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    srv.daemon_threads = True
    srv.serve_forever()


if __name__ == "__main__":
    main()

import os
import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ.get("STORE", "store.json")
LOCK = threading.Lock()


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict) and isinstance(d.get("todos"), list):
            d.setdefault("next_id", max([t["id"] for t in d["todos"]] + [0]) + 1)
            return d
    except Exception:
        pass
    return {"next_id": 1, "todos": []}


def save(d):
    tmp = STORE + ".tmp%d" % threading.get_ident()
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f)
    os.replace(tmp, STORE)


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        if code == 204:
            self.send_response(204)
            self.end_headers()
            return
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def body_json(self):
        try:
            n = int(self.headers.get("content-length") or 0)
            raw = self.rfile.read(n) if n > 0 else b""
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def read_raw_discard(self):
        pass

    def handle_req(self):
        method = self.command
        sp = urlsplit(self.path)
        parts = sp.path.split("/")
        # parts: ['', 'todos'] or ['', 'todos', id]
        body = None
        if method in ("POST", "PATCH"):
            body = self.body_json()
        else:
            try:
                n = int(self.headers.get("content-length") or 0)
                if n > 0:
                    self.rfile.read(n)
            except Exception:
                pass

        nf = ({"error": "not found"})
        if len(parts) == 2 and parts[1] == "todos" and parts[0] == "":
            if method == "POST":
                title = body.get("title") if isinstance(body, dict) else None
                if not isinstance(title, str) or not title.strip():
                    return self.send(400, {"error": "title required"})
                with LOCK:
                    d = load()
                    t = {"id": d["next_id"], "title": title.strip(), "done": False}
                    d["next_id"] += 1
                    d["todos"].append(t)
                    save(d)
                return self.send(201, t)
            if method == "GET":
                with LOCK:
                    d = load()
                todos = sorted(d["todos"], key=lambda t: t["id"])
                q = parse_qs(sp.query).get("done")
                if q:
                    v = q[0]
                    if v == "true":
                        todos = [t for t in todos if t["done"] is True]
                    elif v == "false":
                        todos = [t for t in todos if t["done"] is False]
                return self.send(200, todos)
            return self.send(404, nf)

        if len(parts) == 3 and parts[0] == "" and parts[1] == "todos":
            seg = parts[2]
            if not (seg.isascii() and seg.isdigit() and str(int(seg)) == seg):
                return self.send(404, nf)
            tid = int(seg)
            if method not in ("GET", "PATCH", "DELETE"):
                return self.send(404, nf)
            with LOCK:
                d = load()
                t = next((x for x in d["todos"] if x["id"] == tid), None)
                if t is None:
                    return self.send(404, nf)
                if method == "GET":
                    return self.send(200, t)
                if method == "DELETE":
                    d["todos"] = [x for x in d["todos"] if x["id"] != tid]
                    save(d)
                    return self.send(204)
                # PATCH
                bad = {"error": "bad update"}
                if not isinstance(body, dict):
                    return self.send(400, bad)
                new_title = None
                new_done = None
                if "title" in body:
                    v = body["title"]
                    if not isinstance(v, str) or not v.strip():
                        return self.send(400, bad)
                    new_title = v.strip()
                if "done" in body:
                    v = body["done"]
                    if not isinstance(v, bool):
                        return self.send(400, bad)
                    new_done = v
                if new_title is not None:
                    t["title"] = new_title
                if new_done is not None:
                    t["done"] = new_done
                save(d)
                return self.send(200, t)
        return self.send(404, nf)

    do_GET = do_POST = do_PATCH = do_DELETE = do_PUT = do_HEAD = do_OPTIONS = handle_req


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    srv = ThreadingHTTPServer(("127.0.0.1", port), H)
    srv.daemon_threads = True
    srv.serve_forever()

import os
import re
import json
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
lock = threading.Lock()
with lock:
    conn.execute(
        "CREATE TABLE IF NOT EXISTS notes ("
        "id INTEGER PRIMARY KEY AUTOINCREMENT, "
        "title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"
    )

ID_RE = re.compile(r"^/notes/([0-9]+)$")
MAX_ID = 2**63 - 1


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def nf(self):
        self.send(404, {"error": "not found"})

    def read_body(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def handle_any(self):
        method = self.command
        raw = self.read_body()
        parts = urlsplit(self.path)
        path = parts.path
        try:
            if method == "POST" and path == "/notes":
                return self.create(raw)
            if method == "GET" and path == "/notes":
                return self.list(parts.query)
            m = ID_RE.match(path)
            if m and method in ("GET", "DELETE"):
                nid = int(m.group(1))
                if nid > MAX_ID:
                    return self.nf()
                if method == "GET":
                    return self.get(nid)
                return self.delete(nid)
        except Exception:
            pass
        return self.nf()

    def create(self, raw):
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            obj = None
        bad = lambda: self.send(400, {"error": "invalid note"})
        if not isinstance(obj, dict):
            return bad()
        title = obj.get("title")
        body = obj.get("body")
        tags = obj.get("tags", [])
        if not isinstance(title, str) or not title:
            return bad()
        if not isinstance(body, str):
            return bad()
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            return bad()
        seen = []
        for t in tags:
            t = t.lower()
            if t not in seen:
                seen.append(t)
        with lock:
            cur = conn.execute(
                "INSERT INTO notes (title, body, tags) VALUES (?,?,?)",
                (title, body, json.dumps(seen)),
            )
            nid = cur.lastrowid
        self.send(201, {"id": nid})

    def get(self, nid):
        with lock:
            row = conn.execute(
                "SELECT id, title, body, tags FROM notes WHERE id=?", (nid,)
            ).fetchone()
        if not row:
            return self.nf()
        self.send(200, {"id": row[0], "title": row[1], "body": row[2], "tags": json.loads(row[3])})

    def delete(self, nid):
        with lock:
            cur = conn.execute("DELETE FROM notes WHERE id=?", (nid,))
            n = cur.rowcount
        if n < 1:
            return self.nf()
        self.send(200, {"deleted": nid})

    def list(self, query):
        qs = parse_qs(query)
        tag = qs.get("tag", [None])[0]
        word = qs.get("q", [None])[0]
        if tag is not None:
            tag = tag.lower()
        with lock:
            rows = conn.execute(
                "SELECT id, title, body, tags FROM notes ORDER BY id DESC"
            ).fetchall()
        out = []
        for id_, title, body, tags in rows:
            if tag is not None and tag not in json.loads(tags):
                continue
            if word is not None and word not in title and word not in body:
                continue
            out.append({"id": id_, "title": title})
        self.send(200, out)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H)
    srv.daemon_threads = True
    srv.serve_forever()

import os, json, sys

def sk(s):
    return s.encode("utf-8", "surrogatepass")

def main():
    path = os.path.join(os.environ.get("INPUT", "input"), "packages.json")
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        print("error: not an object")
        return
    if not isinstance(data, dict):
        print("error: not an object")
        return

    valid = {}
    invalid = []
    for k, v in data.items():
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            valid[k] = list(dict.fromkeys(v))
        else:
            invalid.append(k)

    missing = {}
    for p, deps in valid.items():
        for d in deps:
            if d not in valid:
                missing.setdefault(d, set()).add(p)

    # iterative Tarjan over valid edges
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    counter = 0
    for root in sorted(valid, key=sk):
        if root in index:
            continue
        work = [(root, iter([d for d in valid[root] if d in valid]))]
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        while work:
            node, it = work[-1]
            advanced = False
            for w in it:
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, iter([d for d in valid[w] if d in valid])))
                    advanced = True
                    break
                elif w in onstack:
                    low[node] = min(low[node], index[w])
            if advanced:
                continue
            work.pop()
            if work:
                parent = work[-1][0]
                low[parent] = min(low[parent], low[node])
            if low[node] == index[node]:
                comp = []
                while True:
                    w = stack.pop()
                    onstack.discard(w)
                    comp.append(w)
                    if w == node:
                        break
                sccs.append(comp)

    cycles = []
    incycle = set()
    built = {}
    for comp in sccs:  # dependencies first
        if len(comp) > 1 or comp[0] in valid[comp[0]]:
            cycles.append(sorted(comp, key=sk))
            incycle.update(comp)
            continue
        p = comp[0]
        ok = True
        st = 0
        for d in valid[p]:
            if d not in valid or d not in built:
                ok = False
                break
            st = max(st, built[d])
        if ok:
            built[p] = st + 1

    out = []
    stages = {}
    for p, s in built.items():
        stages.setdefault(s, []).append(p)
    for s in sorted(stages):
        out.append("stage %d: %s" % (s, ", ".join(sorted(stages[s], key=sk))))
    cycles.sort(key=lambda c: sk(c[0]))
    for c in cycles:
        out.append("cycle: " + ", ".join(c))
    for m in sorted(missing, key=sk):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m], key=sk))))
    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid, key=sk)))
    blocked = [p for p in valid if p not in built and p not in incycle]
    if blocked:
        out.append("blocked: " + ", ".join(sorted(blocked, key=sk)))
    out.append("built %d of %d" % (len(built), len(valid)))
    sys.stdout.write("\n".join(out) + "\n")

main()

import os
import re
import sys

T = re.compile(r'^([0-9]{2}):([0-9]{2})$')


def parse_time(s):
    m = T.match(s)
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if mi > 59:
        return None
    if h > 23 and not (h == 24 and mi == 0):
        return None
    return h * 60 + mi


def fmt(m):
    return "%02d:%02d" % (m // 60, m % 60)


def main():
    path = os.path.join(os.environ["INPUT"], "bookings.csv")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    skipped = []
    seen = set()
    groups = {}
    for idx, line in enumerate(lines):
        n = idx + 1
        if n == 1:
            continue
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        parts = line.split(",")
        if len(parts) != 5:
            skipped.append(n)
            continue
        room, day, st, en, who = parts
        s = parse_time(st)
        e = parse_time(en)
        if s is None or e is None or e <= s:
            skipped.append(n)
            continue
        key = tuple(parts)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault(room, {}).setdefault(day, []).append((s, e, who))

    out = []
    for room in sorted(groups, key=lambda x: x.encode("utf-8", "surrogateescape")):
        days = groups[room]
        for day in sorted(days, key=lambda x: x.encode("utf-8", "surrogateescape")):
            bk = days[day]
            out.append("%s %s" % (room, day))
            iv = sorted((s, e) for s, e, _ in bk)
            merged = []
            for s, e in iv:
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("  busy " + ", ".join("%s-%s" % (fmt(a), fmt(b)) for a, b in merged))
            free = []
            cur = 540
            for a, b in merged:
                if b <= 540:
                    continue
                if a >= 1080:
                    break
                if a - cur >= 30:
                    free.append((cur, a))
                cur = max(cur, b)
            if 1080 - cur >= 30:
                free.append((cur, 1080))
            if free:
                out.append("  free " + ", ".join("%s-%s" % (fmt(a), fmt(b)) for a, b in free))
            else:
                out.append("  free none")
            conf = []
            for i in range(len(bk)):
                for j in range(i + 1, len(bk)):
                    s = max(bk[i][0], bk[j][0])
                    e = min(bk[i][1], bk[j][1])
                    if s < e:
                        names = sorted([bk[i][2], bk[j][2]],
                                       key=lambda x: x.encode("utf-8", "surrogateescape"))
                        text = "conflict %s/%s %s-%s" % (names[0], names[1], fmt(s), fmt(e))
                        conf.append((s, text))
            conf.sort(key=lambda t: (t[0], t[1].encode("utf-8", "surrogateescape")))
            for _, text in conf:
                out.append("  " + text)
    if skipped:
        out.append("skipped: " + ", ".join(map(str, skipped)))
    else:
        out.append("skipped: none")
    sys.stdout.write("\n".join(out) + "\n")


main()

import os, sys, json

sys.set_int_max_str_digits(0)


class F(float):
    pass


def bad_const(s):
    raise ValueError(s)


def parse(b):
    s = b.decode("utf-8")
    return json.loads(s, parse_float=F, parse_constant=bad_const)


def validate(v, sch, path, errs):
    t = sch.get("type")
    if t == "object":
        if not isinstance(v, dict):
            errs.append((path, "expected object"))
            return
        props = sch.get("properties", {}) or {}
        for r in sch.get("required", []) or []:
            if r not in v:
                errs.append((path + "." + r, "missing required field"))
        for k, val in v.items():
            if k in props:
                validate(val, props[k], path + "." + k, errs)
            elif sch.get("additional", True) is False:
                errs.append((path + "." + k, "unexpected field"))
    elif t == "array":
        if not isinstance(v, list):
            errs.append((path, "expected array"))
            return
        mi = sch.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d items" % mi))
        it = sch.get("items")
        if it is not None:
            for i, e in enumerate(v):
                validate(e, it, "%s[%d]" % (path, i), errs)
    elif t == "string":
        if not isinstance(v, str):
            errs.append((path, "expected string"))
            return
        mn = sch.get("min_length")
        mx = sch.get("max_length")
        en = sch.get("enum")
        if mn is not None and len(v) < mn:
            errs.append((path, "shorter than %d" % mn))
        elif mx is not None and len(v) > mx:
            errs.append((path, "longer than %d" % mx))
        elif en is not None and v not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            ok = False
        elif t == "integer":
            ok = isinstance(v, int)
        else:
            ok = True
        if not ok:
            errs.append((path, "expected " + t))
            return
        mn = sch.get("minimum")
        mx = sch.get("maximum")
        if mn is not None and v < mn:
            errs.append((path, "less than %d" % mn))
        elif mx is not None and v > mx:
            errs.append((path, "greater than %d" % mx))
    elif t == "boolean":
        if not isinstance(v, bool):
            errs.append((path, "expected boolean"))
    elif t == "null":
        if v is not None:
            errs.append((path, "expected null"))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "schema.json"), "rb") as f:
        schema = json.loads(f.read().decode("utf-8"))
    with open(os.path.join(d, "records.jsonl"), "rb") as f:
        data = f.read()
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()
    out = []
    total = 0
    valid = 0
    for n, line in enumerate(lines, 1):
        if line.strip() == b"":
            continue
        total += 1
        try:
            rec = parse(line)
        except Exception:
            out.append("line %d: invalid JSON" % n)
            continue
        errs = []
        validate(rec, schema, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % n)
        else:
            errs.sort(key=lambda e: (e[0].encode("utf-8", "surrogatepass"),
                                     e[1].encode("utf-8", "surrogatepass")))
            for p, m in errs:
                out.append("line %d: %s: %s" % (n, p, m))
    out.append("valid %d of %d" % (valid, total))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))


main()

import os, sys, json, re, hashlib, secrets, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

STORE = os.environ.get("STORE", "store.json")
LOCK = threading.Lock()
NAME_RE = re.compile(r"[a-z0-9_]{3,20}")

def load():
    try:
        with open(STORE) as f:
            d = json.load(f)
        d.setdefault("users", {})
        d.setdefault("sessions", {})
        return d
    except Exception:
        return {"users": {}, "sessions": {}}

STATE = load()

def save():
    tmp = STORE + ".tmp"
    with open(tmp, "w") as f:
        json.dump(STATE, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, STORE)

def now():
    return int(os.environ["CLOCK"])

def h(name, pw):
    return hashlib.sha256(name.encode() + b"\0" + pw.encode("utf-8", "surrogatepass")).hexdigest()

class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        if code == 204:
            self.send_response(204)
            self.end_headers()
            return
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("content-length") or 0)
        raw = self.rfile.read(n) if n else b""
        try:
            d = json.loads(raw.decode("utf-8"))
            return d if isinstance(d, dict) else None
        except Exception:
            return None

    def token(self):
        a = self.headers.get("authorization") or ""
        if a.startswith("Bearer "):
            return a[7:].strip()
        return None

    def session(self, t, t_now):
        if not t:
            return None
        s = STATE["sessions"].get(t)
        if s is None:
            return None
        if t_now >= s["expires"]:
            del STATE["sessions"][t]
            save()
            return None
        return s

    def do_POST(self):
        path = self.path.split("?")[0]
        if path == "/users":
            d = self.body()
            with LOCK:
                name = d.get("name") if d else None
                pw = d.get("password") if d else None
                if (not isinstance(name, str) or not NAME_RE.fullmatch(name)
                        or not isinstance(pw, str) or len(pw.encode("utf-8", "surrogatepass")) < 8):
                    return self.send(400, {"error": "invalid"})
                if name in STATE["users"]:
                    return self.send(409, {"error": "name taken"})
                STATE["users"][name] = {"hash": h(name, pw), "fails": 0,
                                        "locked_until": 0, "logins": 0}
                save()
            return self.send(201, {"name": name})
        if path == "/login":
            d = self.body()
            bad = (401, {"error": "bad credentials"})
            with LOCK:
                name = d.get("name") if d else None
                pw = d.get("password") if d else None
                if not isinstance(name, str) or not isinstance(pw, str):
                    return self.send(*bad)
                u = STATE["users"].get(name)
                if u is None:
                    return self.send(*bad)
                t = now()
                if t < u["locked_until"]:
                    return self.send(429, {"error": "locked"})
                if h(name, pw) != u["hash"]:
                    u["fails"] += 1
                    if u["fails"] >= 3:
                        u["fails"] = 0
                        u["locked_until"] = t + 15 * 60 * 1000
                    save()
                    return self.send(*bad)
                u["fails"] = 0
                u["logins"] += 1
                tok = secrets.token_bytes(16).hex()
                STATE["sessions"][tok] = {"name": name, "expires": t + 1800000}
                save()
            return self.send(200, {"token": tok, "expires_in": 1800})
        if path == "/logout":
            with LOCK:
                t = self.token()
                s = self.session(t, now())
                if s is None:
                    return self.send(401, {"error": "unauthorized"})
                del STATE["sessions"][t]
                save()
            return self.send(204)
        self.send(404, {"error": "not found"})

    def do_GET(self):
        path = self.path.split("?")[0]
        if path == "/me":
            with LOCK:
                t = now()
                tok = self.token()
                s = self.session(tok, t)
                if s is None:
                    return self.send(401, {"error": "unauthorized"})
                s["expires"] = t + 1800000
                save()
                u = STATE["users"][s["name"]]
                return self.send(200, {"name": s["name"], "logins": u["logins"]})
        self.send(404, {"error": "not found"})

    def do_PUT(self):
        self.send(404, {"error": "not found"})
    do_DELETE = do_PATCH = do_PUT

if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H)
    srv.daemon_threads = True
    srv.serve_forever()

import os, re, json, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

LOCK = threading.Lock()
conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("PRAGMA journal_mode=WAL")
conn.execute("PRAGMA synchronous=FULL")
conn.execute("""CREATE TABLE IF NOT EXISTS payments(
    n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL,
    currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)""")
conn.execute("""CREATE TABLE IF NOT EXISTS idem(
    key TEXT PRIMARY KEY, method TEXT, path TEXT, body TEXT, status INTEGER, response TEXT)""")

COLS = "n,account,cents,currency,status,refunded"


def pay(r):
    return {"id": "pay_%d" % r[0], "account": r[1], "cents": r[2],
            "currency": r[3], "status": r[4], "refunded": r[5]}


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def parse_body(raw):
    try:
        return True, json.loads(raw.decode("utf-8"))
    except Exception:
        return False, None


def canon(raw):
    ok, v = parse_body(raw)
    if ok:
        return "j:" + json.dumps(v, sort_keys=True, separators=(",", ":"))
    return "r:" + raw.decode("utf-8", "replace")


def get_row(n):
    return conn.execute("SELECT %s FROM payments WHERE n=?" % COLS, (n,)).fetchone()


def find(pid):
    m = re.fullmatch(r"pay_([0-9]+)", pid)
    if not m:
        return None
    n = int(m.group(1))
    if "pay_%d" % n != pid:
        return None
    return get_row(n)


NF = (404, {"error": "not found"})
INV = (409, {"error": "invalid transition"})


def handle(method, path, query, headers, raw):
    parts = [p for p in path.split("/")]
    # parts[0] == ''
    if method == "GET":
        if path == "/payments":
            acc = query.get("account")
            if not acc:
                return 200, []
            rows = conn.execute("SELECT %s FROM payments WHERE account=? ORDER BY n" % COLS, (acc[0],)).fetchall()
            return 200, [pay(r) for r in rows]
        if len(parts) == 3 and parts[1] == "payments":
            r = find(parts[2])
            return (200, pay(r)) if r else NF
        return NF
    if method != "POST":
        return NF
    is_create = path == "/payments"
    is_refund = len(parts) == 4 and parts[1] == "payments" and parts[3] == "refund"
    is_cap = len(parts) == 4 and parts[1] == "payments" and parts[3] in ("capture", "cancel")
    if not (is_create or is_refund or is_cap):
        return NF
    key = None
    if is_create or is_refund:
        key = headers.get("idempotency-key")
        if key is None:
            return 400, {"error": "missing idempotency key"}
        cb = canon(raw)
        row = conn.execute("SELECT method,path,body,status,response FROM idem WHERE key=?", (key,)).fetchone()
        if row:
            if row[0] == method and row[1] == path and row[2] == cb:
                return row[3], ("RAW", row[4])
            return 409, {"error": "key reused"}
    if is_create:
        ok, b = parse_body(raw)
        if not (ok and isinstance(b, dict) and set(b.keys()) == {"account", "cents", "currency"}
                and isinstance(b["account"], str) and b["account"]
                and is_int(b["cents"]) and b["cents"] > 0
                and b["currency"] in ("EUR", "USD")):
            return 422, {"error": "invalid payment"}
        cur = conn.execute("INSERT INTO payments(account,cents,currency,status,refunded) VALUES(?,?,?,?,0)",
                           (b["account"], b["cents"], b["currency"], "pending"))
        result = (201, pay(get_row(cur.lastrowid)))
    else:
        r = find(parts[2])
        if not r:
            return NF
        n = r[0]
        if is_cap:
            act = parts[3]
            if act == "capture":
                if r[4] == "pending":
                    conn.execute("UPDATE payments SET status='captured' WHERE n=?", (n,))
                elif r[4] != "captured":
                    return INV
            else:
                if r[4] != "pending":
                    return INV
                conn.execute("UPDATE payments SET status='canceled' WHERE n=?", (n,))
            return 200, pay(get_row(n))
        ok, b = parse_body(raw)
        if not (ok and isinstance(b, dict) and is_int(b.get("cents")) and b["cents"] > 0):
            return 422, {"error": "invalid refund"}
        if r[4] != "captured":
            return INV
        if r[5] + b["cents"] > r[2]:
            return 409, {"error": "exceeds captured"}
        nr = r[5] + b["cents"]
        st = "refunded" if nr == r[2] else "captured"
        conn.execute("UPDATE payments SET refunded=?, status=? WHERE n=?", (nr, st, n))
        result = (200, pay(get_row(n)))
    if key is not None and 200 <= result[0] < 300:
        conn.execute("INSERT INTO idem(key,method,path,body,status,response) VALUES(?,?,?,?,?,?)",
                     (key, method, path, canon(raw), result[0], json.dumps(result[1])))
    return result


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def run(self, method):
        try:
            ln = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            ln = 0
        raw = self.rfile.read(ln) if ln > 0 else b""
        u = urlsplit(self.path)
        path = u.path
        query = parse_qs(u.query)
        hd = {k.lower(): v for k, v in self.headers.items()}
        with LOCK:
            try:
                conn.execute("BEGIN IMMEDIATE")
                try:
                    status, body = handle(method, path, query, hd, raw)
                    conn.execute("COMMIT")
                except BaseException:
                    conn.execute("ROLLBACK")
                    raise
            except Exception:
                status, body = 500, {"error": "internal"}
        if isinstance(body, tuple) and body and body[0] == "RAW":
            data = body[1].encode()
        else:
            data = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self): self.run("GET")
    def do_POST(self): self.run("POST")
    def do_PUT(self): self.run("PUT")
    def do_DELETE(self): self.run("DELETE")
    def do_PATCH(self): self.run("PATCH")


