import os, sys, re, json, hashlib

WORD = re.compile(rb'[^\x00-\x2f\x3a-\x40\x5b-\x60\x7b-\x7f]+')


def words_of(data):
    return {w.decode('utf-8', 'replace').lower() for w in WORD.findall(data)}


def main():
    docs = os.environ['DOCS']
    queries = os.environ['QUERIES']
    kv = os.environ['INDEX']

    old = {}
    try:
        with open(kv, 'r') as f:
            old = json.load(f).get('files', {})
    except Exception:
        old = {}

    current = {}
    for root, dirs, files in os.walk(docs):
        for name in files:
            full = os.path.join(root, name)
            if not os.path.isfile(full):
                continue
            rel = os.path.relpath(full, docs).replace(os.sep, '/')
            current[rel] = full

    new = {}
    out = []
    unchanged = 0
    for rel in current:
        with open(current[rel], 'rb') as f:
            data = f.read()
        h = hashlib.sha256(data).hexdigest()
        prev = old.get(rel)
        if prev is None:
            out.append((rel, 'added'))
            new[rel] = {'hash': h, 'words': sorted(words_of(data))}
        elif prev.get('hash') != h:
            out.append((rel, 'changed'))
            new[rel] = {'hash': h, 'words': sorted(words_of(data))}
        else:
            unchanged += 1
            new[rel] = prev
    for rel in old:
        if rel not in current:
            out.append((rel, 'removed'))

    key = lambda p: os.fsencode(p)
    out.sort(key=lambda t: key(t[0]))

    tmp = kv + '.tmp'
    # inverted index: word -> files
    inv = {}
    for rel, info in new.items():
        for w in info['words']:
            inv.setdefault(w, []).append(rel)
    with open(tmp, 'w') as f:
        json.dump({'files': new, 'index': inv}, f)
    os.replace(tmp, kv)

    buf = sys.stdout.buffer

    def emit(s):
        buf.write(os.fsencode(s) if False else s.encode('utf-8', 'surrogateescape'))
        buf.write(b'\n')

    for rel, kind in out:
        emit('%s %s' % (kind, rel))
    emit('unchanged %d' % unchanged)

    qpath = os.path.join(queries, 'queries.txt')
    try:
        with open(qpath, 'rb') as f:
            raw = f.read()
    except Exception:
        raw = b''
    for rawline in raw.split(b'\n'):
        if rawline.endswith(b'\r'):
            rawline = rawline[:-1]
        if not rawline.strip():
            continue
        line = rawline.decode('utf-8', 'surrogateescape')
        qw = words_of(rawline)
        if qw:
            sets = [set(inv.get(w, ())) for w in qw]
            res = set.intersection(*sets)
        else:
            res = set(new)
        res = sorted(res, key=key)
        emit('%s: %s' % (line, ', '.join(res) if res else 'none'))
    buf.flush()


main()

import os
import sys
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    jobs = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                jobs = json.load(f)
        except Exception:
            jobs = {}

    out = []

    # Enqueue
    ep = os.path.join(input_dir, "enqueue.jsonl")
    if os.path.exists(ep):
        with open(ep, "rb") as f:
            text = f.read().decode("utf-8", errors="replace")
        for n, line in enumerate(text.split("\n"), 1):
            if not line.strip():
                continue
            try:
                obj = json.loads(line)
            except Exception:
                obj = None
            if (not isinstance(obj, dict)
                    or not isinstance(obj.get("id"), str)
                    or not isinstance(obj.get("priority"), int)
                    or isinstance(obj.get("priority"), bool)):
                out.append("invalid line %d" % n)
                continue
            jid = obj["id"]
            if jid in jobs:
                out.append("duplicate ID")
                continue
            jobs[jid] = {"priority": obj["priority"], "due": now,
                         "attempts": 0, "state": "pending"}

    # Script
    script = {}
    sp = os.path.join(input_dir, "script.json")
    if os.path.exists(sp):
        try:
            with open(sp, "r", encoding="utf-8") as f:
                script = json.load(f)
            if not isinstance(script, dict):
                script = {}
        except Exception:
            script = {}

    # Work
    due = [(j["priority"], j["due"], jid) for jid, j in jobs.items()
           if j["state"] == "pending" and j["due"] <= now]
    due.sort(key=lambda t: (-t[0], t[1], t[2].encode("utf-8")))
    for _, _, jid in due[:5]:
        j = jobs[jid]
        j["attempts"] += 1
        k = j["attempts"]
        outs = script.get(jid)
        if isinstance(outs, list) and outs:
            outcome = outs[min(k - 1, len(outs) - 1)]
        else:
            outcome = "ok"
        if outcome == "fail":
            if k >= 4:
                j["state"] = "dead"
                out.append("dead %s" % jid)
            else:
                s = 60 * (2 ** (k - 1))
                j["due"] = now + s * 1000
                out.append("retry %s in %d" % (jid, s))
        else:
            j["state"] = "done"
            out.append("done %s" % jid)

    p = sum(1 for j in jobs.values() if j["state"] == "pending")
    d = sum(1 for j in jobs.values() if j["state"] == "done")
    x = sum(1 for j in jobs.values() if j["state"] == "dead")
    out.append("pending %d done %d dead %d" % (p, d, x))

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(jobs, f)
    os.replace(tmp, kv_path)

    sys.stdout.write("\n".join(out) + "\n")


