import os, re, sys

MIN = -2**63
MAX = 2**63 - 1
sys.setrecursionlimit(20000)


class Err(Exception):
    pass


TOK = re.compile(r"\s*(?:(\d+)|([A-Za-z_][A-Za-z0-9_]*)|([-+*/%^(),=]))")


def tokenize(s):
    toks = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = TOK.match(s, pos)
        if not m:
            raise Err("syntax error")
        if m.group(1) is not None:
            toks.append(("int", m.group(1)))
        elif m.group(2) is not None:
            toks.append(("name", m.group(2)))
        else:
            toks.append(("op", m.group(3)))
        pos = m.end()
    return toks


class Parser:
    def __init__(self, toks, pos=0):
        self.t = toks
        self.p = pos

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else None

    def isop(self, o):
        k = self.peek()
        return k is not None and k[0] == "op" and k[1] == o

    def expr(self):
        left = self.term()
        while self.isop("+") or self.isop("-"):
            op = self.t[self.p][1]
            self.p += 1
            right = self.term()
            left = ("bin", op, left, right)
        return left

    def term(self):
        left = self.factor()
        while self.isop("*") or self.isop("/") or self.isop("%"):
            op = self.t[self.p][1]
            self.p += 1
            right = self.factor()
            left = ("bin", op, left, right)
        return left

    def factor(self):
        if self.isop("-"):
            self.p += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.isop("^"):
            self.p += 1
            b = self.factor()
            return ("pow", a, b)
        return a

    def atom(self):
        k = self.peek()
        if k is None:
            raise Err("syntax error")
        if k[0] == "int":
            self.p += 1
            return ("int", int(k[1]))
        if k[0] == "name":
            self.p += 1
            if self.isop("("):
                self.p += 1
                args = [self.expr()]
                while self.isop(","):
                    self.p += 1
                    args.append(self.expr())
                if not self.isop(")"):
                    raise Err("syntax error")
                self.p += 1
                return ("call", k[1], args)
            return ("var", k[1])
        if k[1] == "(":
            self.p += 1
            e = self.expr()
            if not self.isop(")"):
                raise Err("syntax error")
            self.p += 1
            return e
        raise Err("syntax error")


def chk(v):
    if v < MIN or v > MAX:
        raise Err("overflow")
    return v


FUNCS = {"min": 2, "max": 2, "abs": 1}


def ev(n, env):
    k = n[0]
    if k == "int":
        return chk(n[1])
    if k == "var":
        if n[1] not in env:
            raise Err("unknown variable " + n[1])
        return env[n[1]]
    if k == "neg":
        return chk(-ev(n[1], env))
    if k == "call":
        name, args = n[1], n[2]
        if name not in FUNCS:
            raise Err("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    if k == "pow":
        a = ev(n[1], env)
        b = ev(n[2], env)
        if b < 0:
            raise Err("negative exponent")
        if a in (0, 1):
            return 1 if b == 0 else a
        if a == -1:
            return 1 if b % 2 == 0 else -1
        if b > 64:
            raise Err("overflow")
        return chk(a ** b)
    op = n[1]
    a = ev(n[2], env)
    b = ev(n[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if b == 0:
        raise Err("division by zero")
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    if op == "/":
        return chk(q)
    return a - q * b


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "program.txt"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")
    env = {}
    out = []
    for i, line in enumerate(text.split("\n"), 1):
        line = line.replace("\r", "")
        if not line.strip():
            continue
        try:
            toks = tokenize(line)
            name = None
            if toks and toks[0] == ("name", "let"):
                if (len(toks) < 4 or toks[1][0] != "name"
                        or toks[2] != ("op", "=")):
                    raise Err("syntax error")
                name = toks[1][1]
                p = Parser(toks, 3)
            else:
                p = Parser(toks, 0)
            tree = p.expr()
            if p.p != len(toks):
                raise Err("syntax error")
            v = ev(tree, env)
            if name is not None:
                env[name] = v
                out.append("%d: %s = %d" % (i, name, v))
            else:
                out.append("%d: %d" % (i, v))
        except Err as e:
            out.append("%d: error: %s" % (i, e))
        except RecursionError:
            out.append("%d: error: syntax error" % i)
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


