import os, sys, json, hmac, hashlib, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, unquote

DB = os.environ["DB"]
SECRETS = os.environ["SECRETS"]
LOG = os.environ["LOG"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()

TYPES = {"subscription.created", "subscription.activated", "payment.failed", "subscription.canceled"}
TRANS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}


def connect():
    c = sqlite3.connect(DB, timeout=30, isolation_level=None)
    return c


def init():
    c = connect()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS events(
        n INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT UNIQUE NOT NULL,
        subscription TEXT NOT NULL,
        seq INTEGER NOT NULL,
        type TEXT NOT NULL,
        status TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS subs(
        id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS history(
        n INTEGER PRIMARY KEY AUTOINCREMENT,
        subscription TEXT NOT NULL, state TEXT NOT NULL);
    """)
    c.close()


def log(line):
    with open(LOG, "a") as f:
        f.write(line + "\n")


def get_secret():
    with open(os.path.join(SECRETS, "webhook.key"), "rb") as f:
        s = f.read()
    if s.endswith(b"\n"):
        s = s[:-1]
    return s


def apply_event(c, sub, ev_id, typ):
    row = c.execute("SELECT state FROM subs WHERE id=?", (sub,)).fetchone()
    state = row[0] if row else "none"
    allowed, to = TRANS[typ]
    if state in allowed:
        c.execute("INSERT INTO history(subscription,state) VALUES(?,?)", (sub, to))
        return to, True
    log("invalid transition " + ev_id)
    return state, False


def process(ev):
    sub, eid, typ, seq = ev["subscription"], ev["id"], ev["type"], ev["seq"]
    c = connect()
    try:
        c.execute("BEGIN IMMEDIATE")
        if c.execute("SELECT 1 FROM events WHERE id=?", (eid,)).fetchone():
            c.execute("COMMIT")
            return 200, {"status": "duplicate"}
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sub,)).fetchone()
        state, last = (row[0], row[1]) if row else ("none", 0)
        if seq <= last:
            c.execute("INSERT INTO events(id,subscription,seq,type,status) VALUES(?,?,?,?,'stale')",
                      (eid, sub, seq, typ))
            c.execute("COMMIT")
            return 200, {"status": "stale"}
        if seq > last + 1:
            c.execute("INSERT INTO events(id,subscription,seq,type,status) VALUES(?,?,?,?,'queued')",
                      (eid, sub, seq, typ))
            c.execute("COMMIT")
            return 202, {"status": "queued"}
        c.execute("INSERT INTO events(id,subscription,seq,type,status) VALUES(?,?,?,?,'applied')",
                  (eid, sub, seq, typ))
        state, _ = apply_event(c, sub, eid, typ)
        last = seq
        applied = 1
        while True:
            nxt = c.execute(
                "SELECT n,id,type FROM events WHERE subscription=? AND seq=? AND status='queued' ORDER BY n LIMIT 1",
                (sub, last + 1)).fetchone()
            if not nxt:
                break
            c.execute("UPDATE events SET status='applied' WHERE n=?", (nxt[0],))
            # state must be visible to apply_event for later transitions
            c.execute("INSERT OR REPLACE INTO subs(id,state,seq) VALUES(?,?,?)", (sub, state, last))
            state, _ = apply_event(c, sub, nxt[1], nxt[2])
            last += 1
            applied += 1
        c.execute("INSERT OR REPLACE INTO subs(id,state,seq) VALUES(?,?,?)", (sub, state, last))
        c.execute("UPDATE events SET status='stale' WHERE subscription=? AND seq<=? AND status='queued'",
                  (sub, last))
        c.execute("COMMIT")
        return 200, {"status": "applied", "applied": applied}
    except BaseException:
        try:
            c.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        c.close()


def get_sub(sid):
    c = connect()
    try:
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sid,)).fetchone()
        if not row:
            return 404, {"error": "not found"}
        hist = [r[0] for r in c.execute(
            "SELECT state FROM history WHERE subscription=? ORDER BY n", (sid,))]
        return 200, {"id": sid, "state": row[0], "seq": row[1], "history": hist}
    finally:
        c.close()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def body(self):
        n = int(self.headers.get("content-length") or 0)
        return self.rfile.read(n) if n > 0 else b""

    def handle_any(self):
        method = self.command
        body = self.body()
        path = urlsplit(self.path).path
        try:
            if method == "POST" and path == "/webhooks":
                return self.webhook(body)
            if method == "GET" and path.startswith("/subscriptions/"):
                sid = unquote(path[len("/subscriptions/"):])
                if sid and "/" not in sid:
                    with LOCK:
                        code, obj = get_sub(sid)
                    return self.send(code, obj)
            self.send(404, {"error": "not found"})
        except Exception:
            self.send(500, {"error": "internal error"})

    def webhook(self, body):
        sig = self.headers.get("x-signature")
        expected = "sha256=" + hashlib.sha256(get_secret() + b"." + body).hexdigest()
        if sig is None or not hmac.compare_digest(sig.encode("utf-8", "replace"), expected.encode()):
            log("rejected signature")
            return self.send(401, {"error": "bad signature"})
        try:
            ev = json.loads(body.decode("utf-8"))
        except Exception:
            ev = None
        ok = (isinstance(ev, dict)
              and isinstance(ev.get("id"), str)
              and isinstance(ev.get("type"), str) and ev["type"] in TYPES
              and isinstance(ev.get("subscription"), str)
              and isinstance(ev.get("seq"), int) and not isinstance(ev.get("seq"), bool)
              and ev["seq"] >= 1)
        if not ok:
            return self.send(400, {"error": "invalid event"})
        with LOCK:
            code, obj = process(ev)
        self.send(code, obj)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


if __name__ == "__main__":
    init()
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), H)
    srv.daemon_threads = True
    srv.serve_forever()
